from pathlib import Path
p=Path("app/src/main/assets/public/index.html")
h=p.read_text(encoding="utf-8")
h=h.replace("RoboKids LAB · Nivel 1 · V23 Multidispositivo","RoboKids LAB · Nivel 1 · V24 Multidispositivo")
h=h.replace("Acceso alumno V23","Acceso alumno V24").replace("El QR V23","El QR V24").replace("V23 abre esta fase automáticamente.","V24 abre esta fase automáticamente.")
css_marker="</style>"
css='/* V24 · Panel Profesor optimizado según revisión PDF */\n.teacherTopGrid{display:grid;grid-template-columns:minmax(0,1.55fr) minmax(310px,.75fr);gap:16px;align-items:start}\n.teacherSide{display:grid;gap:16px;align-self:start}\n.teacherFullStack{display:grid;gap:16px;margin-top:16px}\n.teacherPhaseCard .toolbar{margin-top:12px}\n.teacherPhaseCard .btn{min-width:120px}\n.teacherMissionGrid{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(240px,.7fr);gap:14px;align-items:end}\n.teacherBottomGrid{display:grid;grid-template-columns:minmax(300px,.65fr) minmax(0,1.35fr);gap:16px}\n.programVisual{display:flex;flex-direction:column;align-items:center}\n.programVisual img{display:block;width:100%;height:190px;max-height:190px;object-fit:contain;object-position:center;background:#fff;border-radius:12px}\n.programVisual .caption{width:100%;margin-top:8px}\n.physicalGrid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}\n.physicalToggle{width:100%;text-align:left;display:flex;align-items:center;justify-content:space-between;gap:10px}\n.physicalToggle.done{background:#e8f8ef!important;color:#176945!important;border:1px solid #61c996!important}\n.participantListCompact{max-height:230px;overflow:auto}\n.teacherSide .teamGrid{grid-template-columns:1fr 1fr}\n.teacherSide .teamBox{padding:10px}\n.teacherSide .score{font-size:22px}\n@media(max-width:1100px){.teacherTopGrid{grid-template-columns:1fr}.teacherBottomGrid{grid-template-columns:1fr}.teacherMissionGrid{grid-template-columns:1fr}.teacherSide .teamGrid{grid-template-columns:repeat(2,1fr)}}\n@media(max-width:640px){.physicalGrid{grid-template-columns:1fr}.teacherSide .teamGrid{grid-template-columns:1fr}.programVisual img{height:160px}}\n'
if "V24 · Panel Profesor optimizado según revisión PDF" not in h: h=h.replace(css_marker,css+"\n"+css_marker,1)
old_teacher='function teacherView(){if(!RK.state)return RK.brand(\'Profesor\')+\'<div class="hero"><small>V23 · Internet + datos móviles + Wi‑Fi</small><h1>Panel del profesor</h1><p>Servidor multidispositivo con acceso LAN o Internet HTTPS.</p></div><div class="card"><h3>Nueva clase</h3><button class="btn" data-ui="create-room">Crear sala</button>\'+(roomCode?\'<p class="muted">Intentando recuperar sala \'+RK.esc(roomCode)+\'…</p>\':\'\')+\'</div>\';var s=RK.state;return RK.brand(\'Profesor\')+RK.hero(s)+\'<div class="layout"><div class="stack"><div class="card"><h3>Inicio de la clase</h3><div class="roomCode">\'+RK.esc(s.roomCode)+\'</div><p class="muted">El QR V23 prioriza acceso público HTTPS cuando está disponible. Sala \'+RK.esc(s.roomCode)+\'.</p>\'+networkPanel(s)+\'</div><div class="card"><h3>Fase de la partida</h3><div class="safariNote"><b>RESPONDER</b> habilita los botones en los iPhone de los alumnos. Al crear la sala y al cambiar de misión, V23 abre esta fase automáticamente.</div>\'+RK.phaseBar(s)+phaseButtons(s)+\'<div class="toolbar" style="margin-top:12px"><button class="btn green" data-act="reveal">Revelar y puntuar</button><button class="btn danger" data-act="reset-question">Reiniciar pregunta</button></div></div><div class="card"><h3>Cartas / pistas</h3>\'+teacherEvidence(s)+\'</div><div class="card"><h3>Pregunta y respuestas</h3>\'+RK.question(s.question,null,false)+\'<div style="margin-top:14px">\'+responseTable(s)+\'</div></div><div class="card"><h3>Programación Scratch / ACECode</h3>\'+RK.program(s.program)+\'</div><div class="card"><h3>Misión y turno</h3><div class="programGrid"><div><label class="muted">Misión</label><select id="missionSelect" class="select">\'+(s.missionOptions||[]).map(function(m){return \'<option value="\'+m.id+\'" \'+(s.missionId===m.id?\'selected\':\'\')+\'>\'+RK.esc(m.title)+\'</option>\';}).join(\'\')+\'</select></div><div><label class="muted">Equipo en turno físico</label><select id="turnSelect" class="select">\'+s.teams.map(function(t){return \'<option value="\'+t.id+\'" \'+(s.turnTeam===t.id?\'selected\':\'\')+\'>\'+t.emoji+\' \'+RK.esc(t.name)+\'</option>\';}).join(\'\')+\'</select></div></div><p class="muted" style="margin-top:10px">Experiencia activa: \'+RK.esc(s.experienceName||\'\')+\'</p></div><div class="card"><h3>Cronómetro del servidor</h3><div class="timer">\'+RK.fmt(s.timer.remainingMs)+\'</div><div class="toolbar"><button class="btn green" data-act="timer-start">▶ Iniciar</button><button class="btn warn" data-act="timer-pause">⏸ Pausar</button><button class="btn secondary" data-timer-reset="60">↺ 60 s</button><button class="btn secondary" data-timer-reset="120">↺ 120 s</button></div></div><div class="card"><h3>Prueba física ACEBOTT</h3><div class="toolbar">\'+s.teams.map(function(t){return \'<button class="btn green" data-pass="\'+t.id+\'">🏅 \'+RK.esc(t.name)+\' · Logrado (+100)</button><button class="btn secondary" data-unpass="\'+t.id+\'">Quitar logro</button>\';}).join(\'\')+\'</div></div></div><div class="stack"><div class="card"><h3>🏅 Ranking Top 4</h3>\'+RK.rank(s)+\'</div><div class="card"><h3>Equipos y conexiones</h3>\'+RK.teams(s)+\'</div><div class="card"><h3>Participantes (\'+s.participantCount+\')</h3>\'+(s.participants||[]).map(function(p){var t=RK.team(p.teamId);return \'<div class="member"><span>\'+t[0]+\' \'+RK.esc(p.name)+\'</span><span class="badge">\'+(p.connected?\'🟢 conectado\':\'⚪ desconectado\')+\'</span></div>\';}).join(\'\')+\'</div></div></div>\';}\n'
new_teacher='function teacherView(){\n  if(!RK.state)return RK.brand(\'Profesor\')+\'<div class="hero"><small>V24 · Internet + datos móviles + Wi‑Fi</small><h1>Panel del profesor</h1><p>Servidor multidispositivo con acceso LAN o Internet HTTPS.</p></div><div class="card"><h3>Nueva clase</h3><button class="btn" data-ui="create-room">Crear sala</button>\'+(roomCode?\'<p class="muted">Intentando recuperar sala \'+RK.esc(roomCode)+\'…</p>\':\'\')+\'</div>\';\n  var s=RK.state;\n  var participants=(s.participants||[]).map(function(p){var t=RK.team(p.teamId);return \'<div class="member"><span>\'+t[0]+\' \'+RK.esc(p.name)+\'</span><span class="badge">\'+(p.connected?\'🟢 conectado\':\'⚪ desconectado\')+\'</span></div>\';}).join(\'\');\n  var missionOpts=(s.missionOptions||[]).map(function(m){return \'<option value="\'+m.id+\'" \'+(s.missionId===m.id?\'selected\':\'\')+\'>\'+RK.esc(m.title)+\'</option>\';}).join(\'\');\n  var turnOpts=s.teams.map(function(t){return \'<option value="\'+t.id+\'" \'+(s.turnTeam===t.id?\'selected\':\'\')+\'>\'+t.emoji+\' \'+RK.esc(t.name)+\'</option>\';}).join(\'\');\n  var physical=\'<div class="physicalGrid">\'+s.teams.map(function(t){var done=!!t.physicalPassed;return \'<button class="btn \'+(done?\'physicalToggle done\':\'secondary physicalToggle\')+\'" data-physical-toggle="\'+t.id+\'" data-passed="\'+(done?\'0\':\'1\')+\'"><span>\'+t.emoji+\' \'+RK.esc(t.name)+\'</span><b>\'+(done?\'✅ Logrado +100\':\'Pendiente\')+\'</b></button>\';}).join(\'\')+\'</div>\';\n  return RK.brand(\'Profesor\')+RK.hero(s)+\n  \'<div class="teacherTopGrid">\'+\n    \'<div class="card"><h3>Inicio de la clase</h3><div class="roomCode">\'+RK.esc(s.roomCode)+\'</div><p class="muted">El QR V24 prioriza acceso público HTTPS cuando está disponible. Sala \'+RK.esc(s.roomCode)+\'.</p>\'+networkPanel(s)+\'</div>\'+\n    \'<div class="teacherSide">\'+\n      \'<div class="card"><h3>🏅 Ranking Top 4</h3>\'+RK.rank(s)+\'</div>\'+\n      \'<div class="card"><h3>Equipos y conexiones</h3>\'+RK.teams(s)+\'</div>\'+\n      \'<div class="card"><h3>Participantes (\'+s.participantCount+\')</h3><div class="participantListCompact">\'+(participants||\'<div class="muted">Todavía no hay participantes conectados.</div>\')+\'</div></div>\'+\n    \'</div>\'+\n  \'</div>\'+\n  \'<div class="teacherFullStack">\'+\n    \'<div class="card teacherPhaseCard"><h3>Fase de la partida</h3><div class="safariNote"><b>RESPONDER</b> habilita las opciones de respuesta de los alumnos. Al crear la sala y al cambiar de misión, V24 abre esta fase automáticamente.</div>\'+phaseButtons(s)+\'<div class="toolbar"><button class="btn green" data-act="reveal">Revelar y puntuar</button><button class="btn danger" data-act="reset-question">Reiniciar pregunta</button></div></div>\'+\n    \'<div class="card"><h3>Misión y turno</h3><div class="teacherMissionGrid"><div><label class="muted">Misión</label><select id="missionSelect" class="select">\'+missionOpts+\'</select></div><div><label class="muted">Equipo en turno físico</label><select id="turnSelect" class="select">\'+turnOpts+\'</select></div></div><p class="muted" style="margin:10px 0 0">Experiencia activa: <b>\'+RK.esc(s.experienceName||\'\')+\'</b></p></div>\'+\n    \'<div class="card"><h3>Cartas / pistas</h3>\'+teacherEvidence(s)+\'</div>\'+\n    \'<div class="card"><h3>Pregunta y respuestas</h3>\'+RK.question(s.question,null,false)+\'<div style="margin-top:14px">\'+responseTable(s)+\'</div></div>\'+\n    \'<div class="card"><h3>Programación Scratch / ACECode</h3>\'+RK.program(s.program)+\'</div>\'+\n    \'<div class="teacherBottomGrid">\'+\n      \'<div class="card"><h3>Cronómetro del servidor</h3><div class="timer">\'+RK.fmt(s.timer.remainingMs)+\'</div><div class="toolbar"><button class="btn green" data-act="timer-start">▶ Iniciar</button><button class="btn warn" data-act="timer-pause">⏸ Pausar</button><button class="btn secondary" data-timer-reset="60">↺ 60 s</button><button class="btn secondary" data-timer-reset="120">↺ 120 s</button></div></div>\'+\n      \'<div class="card"><h3>Prueba física ACEBOTT</h3><p class="muted">Cada equipo tiene un único control. Tocá para alternar entre Pendiente y Logrado (+100).</p>\'+physical+\'</div>\'+\n    \'</div>\'+\n  \'</div>\';\n}\n'
if old_teacher not in h: raise SystemExit("No se encontró teacherView V23")
h=h.replace(old_teacher,new_teacher,1)
old_click="document.addEventListener('click',function(e){var b=e.target.closest('button');if(!b)return;if(b.dataset.ui==='create-room')createRoom();if(b.dataset.ui==='player-join'){playerName=document.getElementById('playerName').value.trim();roomCode=document.getElementById('playerRoom').value.trim().toUpperCase();playerTeam=document.getElementById('playerTeam').value;if(!playerName||!roomCode)return alert('Completá nombre y código.');localStorage.setItem('rk_v20_safari_player_name',playerName);localStorage.setItem('rk_v20_safari_player_team',playerTeam);localStorage.setItem('rk_v20_safari_player_room',roomCode);joinCurrent();}if(b.dataset.ui==='screen-join'){roomCode=document.getElementById('screenRoom').value.trim().toUpperCase();localStorage.setItem('rk_v20_safari_screen_room',roomCode);joinCurrent();}if(b.dataset.ui==='station-join'){roomCode=document.getElementById('stationRoom').value.trim().toUpperCase();stationTeam=document.getElementById('stationTeam').value;localStorage.setItem('rk_v20_safari_station_room',roomCode);localStorage.setItem('rk_v20_safari_station_team',stationTeam);joinCurrent();}if(b.dataset.ui==='network-use'){var sel=document.getElementById('networkSelect');if(sel&&sel.value){RK.networkBase=sel.value;localStorage.setItem('rk_v20_safari_network_base',RK.networkBase);render();}}if(b.dataset.ui==='manual-use'){var v=(document.getElementById('manualBase').value||'').trim().replace(/\/$/,'');if(!/^https?:\/\//i.test(v))v='http://'+v;if(v){RK.networkBase=v;localStorage.setItem('rk_v20_safari_network_base',v);render();}}if(b.dataset.ui==='copy-link'&&RK.state){copyText(studentUrl(RK.networkBase,RK.state.roomCode));}if(b.dataset.phase)action('set-phase',{phase:b.dataset.phase});if(b.dataset.act)action(b.dataset.act);if(b.dataset.timerReset)action('timer-reset',{seconds:Number(b.dataset.timerReset)});if(b.dataset.pass)action('physical-pass',{teamId:b.dataset.pass,passed:true});if(b.dataset.unpass)action('physical-pass',{teamId:b.dataset.unpass,passed:false});if(b.dataset.evidence)action('toggle-evidence',{evidenceId:b.dataset.evidence,opened:b.dataset.open==='1'});if(b.dataset.answer){e.preventDefault();action('answer',{value:b.dataset.answer});}if(b.dataset.st)action('station-status',{value:b.dataset.st});if(b.dataset.ob)action('station-observation',{value:b.dataset.ob});});\n"
new_click="document.addEventListener('click',function(e){var b=e.target.closest('button');if(!b)return;if(b.dataset.physicalToggle){action('physical-pass',{teamId:b.dataset.physicalToggle,passed:b.dataset.passed==='1'});return;}if(b.dataset.ui==='create-room')createRoom();if(b.dataset.ui==='player-join'){playerName=document.getElementById('playerName').value.trim();roomCode=document.getElementById('playerRoom').value.trim().toUpperCase();playerTeam=document.getElementById('playerTeam').value;if(!playerName||!roomCode)return alert('Completá nombre y código.');localStorage.setItem('rk_v20_safari_player_name',playerName);localStorage.setItem('rk_v20_safari_player_team',playerTeam);localStorage.setItem('rk_v20_safari_player_room',roomCode);joinCurrent();}if(b.dataset.ui==='screen-join'){roomCode=document.getElementById('screenRoom').value.trim().toUpperCase();localStorage.setItem('rk_v20_safari_screen_room',roomCode);joinCurrent();}if(b.dataset.ui==='station-join'){roomCode=document.getElementById('stationRoom').value.trim().toUpperCase();stationTeam=document.getElementById('stationTeam').value;localStorage.setItem('rk_v20_safari_station_room',roomCode);localStorage.setItem('rk_v20_safari_station_team',stationTeam);joinCurrent();}if(b.dataset.ui==='network-use'){var sel=document.getElementById('networkSelect');if(sel&&sel.value){RK.networkBase=sel.value;localStorage.setItem('rk_v20_safari_network_base',RK.networkBase);render();}}if(b.dataset.ui==='manual-use'){var v=(document.getElementById('manualBase').value||'').trim().replace(/\/$/,'');if(!/^https?:\/\//i.test(v))v='http://'+v;if(v){RK.networkBase=v;localStorage.setItem('rk_v20_safari_network_base',v);render();}}if(b.dataset.ui==='copy-link'&&RK.state){copyText(studentUrl(RK.networkBase,RK.state.roomCode));}if(b.dataset.phase)action('set-phase',{phase:b.dataset.phase});if(b.dataset.act)action(b.dataset.act);if(b.dataset.timerReset)action('timer-reset',{seconds:Number(b.dataset.timerReset)});if(b.dataset.pass)action('physical-pass',{teamId:b.dataset.pass,passed:true});if(b.dataset.unpass)action('physical-pass',{teamId:b.dataset.unpass,passed:false});if(b.dataset.evidence)action('toggle-evidence',{evidenceId:b.dataset.evidence,opened:b.dataset.open==='1'});if(b.dataset.answer){e.preventDefault();action('answer',{value:b.dataset.answer});}if(b.dataset.st)action('station-status',{value:b.dataset.st});if(b.dataset.ob)action('station-observation',{value:b.dataset.ob});});\n"
if old_click not in h: raise SystemExit("No se encontró handler click V23")
h=h.replace(old_click,new_click,1)
p.write_text(h,encoding="utf-8")
print("V24 Android web UI patched")
